# Map all compartment contents by creating shape fingerprints
def get_shape_fingerprint(comp):
    """Convert a 4x4 compartment to a simple fingerprint"""
    # Get unique non-zero values and their positions relative to center
    shape_data = {}
    for r in range(4):
        for c in range(4):
            val = comp[r][c]
            if val > 0:
                if val not in shape_data:
                    shape_data[val] = []
                shape_data[val].append((r, c))
    return str(sorted(shape_data.keys())) + "_" + str(sorted([sorted(shape_data[k]) for k in shape_data]))

compartment_shapes = {}
for r0 in [0, 5, 10, 15, 20]:
    for c0 in [0, 5, 10, 15, 20]:
        comp = [[grid[r0+dr][c0+dc] for dc in range(4)] for dr in range(4)]

        vals = set()
        for r in range(4):
            for c in range(4):
                v = comp[r][c]
                if v > 0:
                    vals.add(v)

        if vals:
            fp = get_shape_fingerprint(comp)
            compartment_shapes[(r0//5, c0//5)] = {
                'values': sorted(vals),
                'fp': fp
            }

print("Compartment shapes:")
for k, v in compartment_shapes.items():
