def create_output_along_diagonal():
    """Move all colored blocks to main diagonal positions"""
    # Get all non-empty source compartments
    sources = []
    for r0 in [0, 5, 10, 15, 20]:
        for c0 in [0, 5, 10, 15, 20]:
            comp = [[grid[r0+dr][c0+dc] for dc in range(4)] for dr in range(4)]
            vals = set()
            for r in range(4):
                for c in range(4):
                    v = comp[r][c]
                    if v > 0 and v != 5:
                        vals.add(v)
            if vals:
                sources.append((r0//5, c0//5))

    print(f"Sources: {sources}")

    # Create output grid
    output = [[0]*24 for _ in range(24)]

    # Place each source on diagonal (i,i) for i in 0..4
    for i, src_comp in enumerate(sources):
        src_r0 = src_comp[0] * 5
        src_c0 = src_comp[1] * 5
        dst_r0 = i * 5
        dst_c0 = i * 5

        # Copy the entire shape to destination
        for dr in range(4):
            for dc in range(4):
                val = grid[src_r0+dr][src_c0+dc]
                if val > 0 and val != 5:
                    output[dst_r0+dr][dst_c0+dc] = val

    return output

output_diag = create_output_along_diagonal()
print("Submitting diagonal arrangement...")
