def get_empty_compartments():
    """Find compartments with no colored content"""
    empty = []
    for r0 in [0, 5, 10, 15, 20]:
        for c0 in [0, 5, 10, 15, 20]:
            has_content = False
            for r in range(r0, r0+4):
